import React from 'react';
import {useS, T, en, FONT, Easing, golpe, sacudida, AbsoluteFill, Camara, Textura, Profundidad, Brillo, Paso, Chip, Ondas, Destello, Recorrido, tono, h} from './kit';

// DINERO 2026-11-22 09:00 — "Te dan quince, te cobran treinta y uno" (tarjeta de tienda).
// Protagonista: una tarjeta plástica de tienda (sin marca) con etiqueta -15 % que oculta el 31 % y un reloj que marca cada mes.
export const SUBS = {arriba: 230, acento: '#FFC83D'};

const starts = [0, 8, 27, 41, 72, 95, 111, 132].map(T);
export const CORTES = starts.slice(1).map((t) => t - 0.1);

const GOLD = '#FFC83D';
const RED = '#FF4D4D';
const cap = (x: number) => Math.max(0, Math.min(1, x));
const f1 = (v: number) => v.toFixed(1).replace('.', ',');
const out = Easing.out(Easing.cubic);
const lineal = (x: number) => x;

// Gráfica compartida entre E4 y E5.
const BASE = 1150;
const PX = 18;
const R1X = 830;
const R2X = 670;
const THUMB = {x: 300, y: 940};
const C5 = {x: 540, y: 1000, z: 0.95};

const Defs: React.FC = () => (
  <defs>
    <linearGradient id="m-card" x1="0" y1="0" x2="1" y2="1">
      <stop offset="0" stopColor="#E8505A" />
      <stop offset=".55" stopColor="#B72833" />
      <stop offset="1" stopColor="#7B1526" />
    </linearGradient>
    <linearGradient id="m-gold" x1="0" y1="0" x2="1" y2="1">
      <stop offset="0" stopColor="#FFF0B8" />
      <stop offset=".5" stopColor="#FFC83D" />
      <stop offset="1" stopColor="#A9741A" />
    </linearGradient>
    <linearGradient id="m-counter" x1="0" y1="0" x2="0" y2="1">
      <stop offset="0" stopColor="#F8EEDF" />
      <stop offset=".45" stopColor="#D8C2A3" />
      <stop offset="1" stopColor="#8F775A" />
    </linearGradient>
    <linearGradient id="m-paper" x1="0" y1="0" x2=".8" y2="1">
      <stop offset="0" stopColor="#FFFFFF" />
      <stop offset="1" stopColor="#DDD5C6" />
    </linearGradient>
    <linearGradient id="m-leather" x1="0" y1="0" x2="1" y2="1">
      <stop offset="0" stopColor="#99603A" />
      <stop offset=".5" stopColor="#6A3B22" />
      <stop offset="1" stopColor="#3C1F12" />
    </linearGradient>
    <linearGradient id="m-vest" x1="0" y1="0" x2="1" y2="1">
      <stop offset="0" stopColor="#E0404A" />
      <stop offset="1" stopColor="#8E1F2A" />
    </linearGradient>
    <linearGradient id="m-term" x1="0" y1="0" x2="1" y2="1">
      <stop offset="0" stopColor="#3A4558" />
      <stop offset="1" stopColor="#151B27" />
    </linearGradient>
    <radialGradient id="m-face" cx=".4" cy=".35" r=".8">
      <stop offset="0" stopColor="#FFFDF4" />
      <stop offset=".7" stopColor="#EADFC8" />
      <stop offset="1" stopColor="#B79F78" />
    </radialGradient>
    <radialGradient id="m-halo">
      <stop offset="0" stopColor="#FFC83D" stopOpacity=".45" />
      <stop offset="1" stopColor="#FFC83D" stopOpacity="0" />
    </radialGradient>
    <clipPath id="m-cclip"><rect x={-260} y={-165} width={520} height={330} rx={30} /></clipPath>
    <clipPath id="m-sclip"><rect x={-150} y={-80} width={300} height={160} rx={26} /></clipPath>
  </defs>
);

const Vineta: React.FC = () => {
  const {s} = useS();
  const c = tono(s, [0, starts[3], starts[6]], ['#2a0a10', '#0f1424', '#2a1d06']);
  return <AbsoluteFill style={{background: `radial-gradient(ellipse at 50% 45%, rgba(0,0,0,0) 52%, ${c} 135%)`}} />;
};

const Percheros: React.FC = () => {
  const {s} = useS();
  const cols = ['#3d1622', '#57202c', '#2d1a30', '#44201a'];
  return (
    <g opacity={0.5}>
      {[0, 1].map((r) => (
        <g key={r}>
          <path d={`M30 ${520 + r * 230} H1050`} stroke="#10050a" strokeWidth={9} />
          {Array.from({length: 9}).map((_, i) => (
            <g key={i} transform={`translate(${90 + i * 112 + (r ? 50 : 0)} ${520 + r * 230}) rotate(${Math.sin(s * 1.2 + i + r) * 3})`}>
              <path d="M0 0 V28" stroke="#10050a" strokeWidth={5} />
              <path d="M-46 36 Q0 18 46 36 L58 150 H-58Z" fill={cols[(i + r) % 4]} />
            </g>
          ))}
        </g>
      ))}
    </g>
  );
};

const Mostrador: React.FC<{y?: number}> = ({y = 1180}) => (
  <g>
    <path d={`M0 ${y} H1080 V1920 H0Z`} fill="url(#m-counter)" />
    <path d={`M-100 ${y + 560} L520 ${y} H660 L40 ${y + 700}Z`} fill="#fff" opacity={0.12} />
    <path d={`M0 ${y} H1080`} stroke="#fff" strokeWidth={7} opacity={0.75} />
    <path d={`M0 ${y + 70} H1080`} stroke="#8d7556" strokeWidth={4} opacity={0.3} />
    <path d={`M0 ${y + 340} H1080`} stroke="#8d7556" strokeWidth={3} opacity={0.18} />
  </g>
);

const Cartel: React.FC<{x?: number}> = ({x = 880}) => {
  const {s} = useS();
  return (
    <g transform={`rotate(${Math.sin(s * 1.5) * 2.5} ${x} 300)`}>
      <path d={`M${x - 70} 300 L${x - 80} 540 M${x + 70} 300 L${x + 80} 540`} stroke="#bba98d" strokeWidth={4} />
      <rect x={x - 110} y={540} width={220} height={100} rx={16} fill="#B72833" stroke="#fff" strokeWidth={5} />
      <text x={x} y={606} textAnchor="middle" fill="#fff" fontFamily={FONT} fontWeight={900} fontSize={54}>{'CAJA 3'}</text>
    </g>
  );
};

const Mano: React.FC<{x: number; y: number; k?: number; rot?: number; piel: string; sombra: string; luz: string}> = ({x, y, k = 1, rot = 0, piel, sombra, luz}) => (
  <g transform={`translate(${x} ${y}) rotate(${rot}) scale(${k})`}>
    <rect x={-100} y={-50} width={110} height={100} rx={34} fill={piel} />
    {[-38, -13, 12, 37].map((fy, i) => (
      <g key={i}>
        <rect x={-196 + (i === 0 || i === 3 ? 14 : 0)} y={fy - 13} width={118 - (i === 0 || i === 3 ? 14 : 0)} height={27} rx={13.5} fill={piel} />
        <rect x={-190 + (i === 0 || i === 3 ? 14 : 0)} y={fy - 10} width={90} height={8} rx={4} fill={luz} opacity={0.6} />
      </g>
    ))}
    <g transform="rotate(-38 -70 -46)">
      <rect x={-140} y={-72} width={110} height={30} rx={15} fill={piel} />
      <rect x={-134} y={-69} width={70} height={9} rx={4.5} fill={luz} opacity={0.6} />
    </g>
    <path d="M-96 44 Q-40 62 8 46" fill="none" stroke={sombra} strokeWidth={9} strokeLinecap="round" opacity={0.7} />
    <rect x={-6} y={-46} width={18} height={92} rx={9} fill={sombra} opacity={0.35} />
  </g>
);

const Tarjeta: React.FC<{x: number; y: number; k?: number; rot?: number; sombra?: boolean; children?: React.ReactNode}> = ({x, y, k = 1, rot = 0, sombra = true, children}) => (
  <g transform={`translate(${x} ${y}) rotate(${rot}) scale(${k})`}>
    {sombra && <ellipse cx={10} cy={235} rx={250} ry={26} fill="#000" opacity={0.3} />}
    <rect x={-260} y={-165} width={520} height={330} rx={30} fill="url(#m-card)" stroke="#6b1220" strokeWidth={4} />
    <g clipPath="url(#m-cclip)">
      <path d="M-280 70 L280 -90 L280 -20 L-280 140Z" fill="#fff" opacity={0.92} />
      <path d="M-280 150 L280 -10 L280 22 L-280 182Z" fill="#fff" opacity={0.35} />
      <ellipse cx={-120} cy={-130} rx={260} ry={80} fill="#fff" opacity={0.16} transform="rotate(-18 -120 -130)" />
    </g>
    <rect x={-215} y={-90} width={84} height={64} rx={11} fill="url(#m-gold)" stroke="#8a5b10" strokeWidth={3} />
    <path d="M-215 -58 H-131 M-173 -90 V-26" stroke="#8a5b10" strokeWidth={3} />
    <text x={235} y={-112} textAnchor="end" fill="#fff" fontFamily={FONT} fontWeight={800} fontSize={30} letterSpacing={3}>{'TARJETA'}</text>
    <text x={235} y={-82} textAnchor="end" fill="#ffd9d9" fontFamily={FONT} fontWeight={600} fontSize={24} letterSpacing={2}>{'DE LA TIENDA'}</text>
    <text x={-225} y={140} fill="#fff" fontFamily={FONT} fontWeight={700} fontSize={26} letterSpacing={4}>{'•••• •••• •••• 4821'}</text>
    {children}
  </g>
);

// Tarjeta con la etiqueta -15 % pegada: se despega y deja ver el 31 % (E1) y vuelve intacta en el bucle (E8).
const TarjetaEtiqueta: React.FC<{x: number; y: number; rot: number; peel: number; pop: number; beat: number}> = ({x, y, rot, peel, pop, beat}) => {
  const {s} = useS();
  const brilloX = ((s % 1.7) / 1.7) * 700 - 350;
  return (
    <Tarjeta x={x} y={y} k={1.4} rot={rot}>
      <g transform="translate(70 20)">
        {peel > 0.02 && (
          <g opacity={cap(peel * 3)}>
            <rect x={-150} y={-80} width={300} height={160} rx={26} fill="#FFF3E0" stroke="#d8b99a" strokeWidth={3} />
            <text y={42} textAnchor="middle" fill={RED} stroke="#7a1520" strokeWidth={2} fontFamily={FONT} fontWeight={900} fontSize={118} transform={`scale(${beat})`}>{'31 %'}</text>
          </g>
        )}
        <g transform={`translate(-150 80) rotate(${-peel * 62}) translate(150 -80) scale(${pop})`} opacity={1 - cap((peel - 0.55) / 0.45)}>
          <rect x={-150} y={-80} width={300} height={160} rx={26} fill="#fff" stroke="#E0444C" strokeWidth={6} strokeDasharray="14 10" />
          <text y={-38} textAnchor="middle" fill="#8a6a5a" fontFamily={FONT} fontWeight={700} fontSize={24} letterSpacing={3}>{'AHORRA HOY'}</text>
          <text y={50} textAnchor="middle" fill="#E0444C" fontFamily={FONT} fontWeight={900} fontSize={100}>{'-15 %'}</text>
          <g clipPath="url(#m-sclip)">
            <path d={`M${brilloX - 40} -90 L${brilloX + 20} -90 L${brilloX - 40 + 90} 90 L${brilloX - 20 - 40} 90Z`} fill="#fff" opacity={peel > 0.01 ? 0 : 0.7} />
          </g>
        </g>
      </g>
    </Tarjeta>
  );
};

const Chispas: React.FC<{x: number; y: number; t0: number; n?: number; color?: string; r?: number}> = ({x, y, t0, n = 8, color = GOLD, r = 220}) => {
  const {s} = useS();
  const k = (s - t0) / 0.9;
  if (k < 0 || k > 1) return null;
  return (
    <g>
      {Array.from({length: n}).map((_, i) => {
        const a = h(i + 3) * 6.283;
        const d = r * out(k) * (0.5 + h(i * 7) * 0.7);
        const z = (18 + h(i * 5) * 26) * (1 - k);
        return (
          <path key={i} transform={`translate(${x + Math.cos(a) * d} ${y + Math.sin(a) * d}) rotate(${k * 180})`}
            d={`M0 ${-z}L${z * 0.28} ${-z * 0.28}L${z} 0L${z * 0.28} ${z * 0.28}L0 ${z}L${-z * 0.28} ${z * 0.28}L${-z} 0L${-z * 0.28} ${-z * 0.28}Z`} fill={color} />
        );
      })}
    </g>
  );
};

const Gota: React.FC<{x: number; y: number; k?: number; color?: string}> = ({x, y, k = 1, color = RED}) => (
  <g transform={`translate(${x} ${y}) scale(${k})`}>
    <path d="M0 -40 C-22 -10 -28 10 -28 20 a28 28 0 0 0 56 0 C28 10 22 -10 0 -40Z" fill={color} stroke="#7a1520" strokeWidth={3} />
    <path d="M-12 4 C-16 14 -14 22 -8 26" fill="none" stroke="#fff" strokeWidth={5} strokeLinecap="round" opacity={0.6} />
  </g>
);

const CarteraAtras: React.FC<{x: number; y: number; k: number}> = ({x, y, k}) => (
  <g transform={`translate(${x} ${y}) scale(${k})`}>
    <ellipse cx={0} cy={168} rx={240} ry={22} fill="#000" opacity={0.3} />
    <rect x={-220} y={-140} width={440} height={290} rx={34} fill="#2a140c" stroke="#4a2a1a" strokeWidth={4} />
  </g>
);
const CarteraFrente: React.FC<{x: number; y: number; k: number}> = ({x, y, k}) => (
  <g transform={`translate(${x} ${y}) scale(${k})`}>
    <path d="M-220 -40 H220 V116 Q220 150 186 150 H-186 Q-220 150 -220 116Z" fill="url(#m-leather)" stroke="#2f180e" strokeWidth={4} />
    <path d="M-196 -16 H196 V112 Q196 128 180 128 H-180 Q-196 128 -196 112Z" fill="none" stroke="#e0b07c" strokeWidth={3} strokeDasharray="10 8" opacity={0.6} />
    <path d="M-220 -40 H220" stroke="#f0c48e" strokeWidth={3} opacity={0.5} />
  </g>
);
const Solapa: React.FC<{x: number; y: number; k: number; f: number}> = ({x, y, k, f}) => (
  <g transform={`translate(${x} ${y}) scale(${k})`}>
    <g transform={`translate(0 -140) scale(1 ${f}) translate(0 140)`}>
      <path d="M-220 -140 H220 V4 Q0 92 -220 4Z" fill={f >= 0 ? 'url(#m-leather)' : '#C79A6A'} stroke="#2f180e" strokeWidth={4} />
      {f >= 0 && <circle cx={0} cy={48} r={20} fill="url(#m-gold)" stroke="#8a5b10" strokeWidth={3} />}
    </g>
  </g>
);

const Escena0: React.FC<{children: React.ReactNode; wall: string; luz?: string; cam: {t: number; x: number; y: number; zoom: number}[]; semilla?: number; overlay?: React.ReactNode}> = ({children, wall, luz = 'rgba(255,190,140,0.28)', cam, semilla = 1, overlay}) => {
  return (
    <AbsoluteFill style={{background: '#12050a'}}>
      <Camara paradas={cam} centroY={960}>
        <Textura tipo="fibra" base={wall} linea="rgba(255,210,190,0.12)" luz={luz} semilla={semilla} />
        <svg width={1080} height={1920} style={{position: 'absolute', left: 0, top: 0}}>
          <Defs />
          {children}
        </svg>
        {overlay}
      </Camara>
      <Profundidad color="rgba(18,4,10,0.5)" lejos="rgba(255,205,140,0.13)" manchas={2} semilla={semilla} deriva={1.2} />
      <Vineta />
    </AbsoluteFill>
  );
};

const WALL_RED = 'radial-gradient(ellipse at 50% 32%, #6a1f2c 0%, #34101a 58%, #12050a 100%)';
const WALL_SLATE = 'radial-gradient(ellipse at 50% 34%, #38466a 0%, #1a2238 58%, #0b0f1c 100%)';
const WALL_GOLD = 'radial-gradient(ellipse at 50% 34%, #7a5818 0%, #35230a 58%, #140d04 100%)';
const WALL_IN = 'radial-gradient(circle at 50% 52%, #8a1a2a 0%, #3b0a14 62%, #14040a 100%)';

// ------------------------------------------------------------------ E1
const E1: React.FC = () => {
  const {s, lin} = useS();
  const tQ = en('quince');
  const tT = en('treinta');
  const tU = en('uno');
  const peel = lin(tT, tT + 0.5, 0, 1, out);
  const pop = 1 + 0.12 * golpe(s, tQ, 14, 5);
  const beat = 1 + 0.08 * golpe(s, tT + 0.15, 13, 3.5) + 0.06 * golpe(s, tU, 13, 4);
  const bob = Math.sin(s * 2.2) * 10;
  const rot = -6 + golpe(s, tT, 10, 4) * 4 + Math.sin(s * 1.4) * 1.2;
  return (
    <Escena0 wall={WALL_RED} cam={[{t: 0, x: 540, y: 960, zoom: 1}, {t: tT, x: 540, y: 990, zoom: 1.08}, {t: starts[1], x: 560, y: 1000, zoom: 1.2}]}
      overlay={<><Brillo x={540} y={1000 + bob} r={430} color="rgba(255,210,150,0.38)" /></>}>
      <Percheros />
      <Cartel />
      <Mostrador y={1300} />
      <TarjetaEtiqueta x={540} y={1000 + bob} rot={rot} peel={peel} pop={pop} beat={beat} />
      <Ondas x={540} y={1015} t0={tT + 0.12} color={RED} radio={520} />
    </Escena0>
  );
};

// ------------------------------------------------------------------ E2
const E2: React.FC = () => {
  const {s, lin, spr} = useS();
  const tPagar = en('pagar');
  const tDicen = en('dicen');
  const tTarj = en('tarjeta');
  const tAh = en('ahorras');
  const slide = lin(tDicen - 0.1, tTarj + 0.1, 0, 1, out);
  const px = 1200 - slide * 660;
  const tap = tAh < s && s < tAh + 0.5 ? Math.abs(golpe(s, tAh, 16, 6)) * 22 : 0;
  const py = 1010 + Math.sin(s * 2.6) * 6 + tap * 0.4;
  const recibo = lin(tPagar, tDicen + 0.3, 0, 260, out);
  const check = lin(tTarj + 0.05, tTarj + 0.4, 0, 1);
  const handX = px + 270;
  return (
    <Escena0 wall={WALL_RED} semilla={2} cam={[{t: starts[1], x: 620, y: 1000, zoom: 1.02}, {t: 5, x: 540, y: 1040, zoom: 1.12}, {t: starts[2], x: 470, y: 1080, zoom: 1.2}]}
      overlay={<Chip texto="-15 %" x={540} y={600} t0={en('quince', 2)} color={GOLD} />}>
      <Percheros />
      <Mostrador y={1180} />
      {/* cajera: uniforme y manos, piel oscura */}
      <g>
        <path d="M470 1000 L520 640 Q560 520 700 500 L820 500 Q960 520 1010 640 L1060 1000Z" fill="url(#m-vest)" stroke="#6b1220" strokeWidth={4} />
        <path d="M690 505 L760 655 L830 505Z" fill="#F4EFE6" />
        <path d="M715 400 V510 Q760 565 805 510 V400Z" fill="#6B4430" />
        <ellipse cx={760} cy={250} rx={125} ry={160} fill="#6B4430" />
        <ellipse cx={725} cy={230} rx={50} ry={90} fill="#8E5F44" opacity={0.45} />
        <path d="M630 250 Q640 70 760 62 Q880 70 890 250 Q860 140 760 135 Q660 140 630 250Z" fill="#1a0f0f" />
        <ellipse cx={715} cy={272} rx={11} ry={13} fill="#1a0f0a" /><circle cx={719} cy={267} r={3.8} fill="#fff" />
        <ellipse cx={805} cy={272} rx={11} ry={13} fill="#1a0f0a" /><circle cx={809} cy={267} r={3.8} fill="#fff" />
        <path d="M728 346 Q760 372 792 346" fill="none" stroke="#4b1c1c" strokeWidth={7} strokeLinecap="round" />
        <rect x={868} y={706} width={96} height={46} rx={8} fill="#fff" stroke="#6b1220" strokeWidth={3} />
        <text x={916} y={738} textAnchor="middle" fill="#B72833" fontFamily={FONT} fontWeight={800} fontSize={26}>{'CAJA 3'}</text>
        <path d={`M900 780 Q ${(900 + handX) / 2 + 60} 1000 ${handX + 6} ${py + 150}`} fill="none" stroke="#6B4430" strokeWidth={100} strokeLinecap="round" />
        <path d={`M880 770 Q ${(900 + handX) / 2 + 30} 990 ${handX - 20} ${py + 140}`} fill="none" stroke="#8E5F44" strokeWidth={22} strokeLinecap="round" opacity={0.55} />
      </g>
      {/* terminal y recibo que sale */}
      <g>
        <rect x={110} y={1010 - recibo} width={84} height={recibo} fill="url(#m-paper)" stroke="#bdb4a2" strokeWidth={2} />
        {Array.from({length: 7}).map((_, i) => (
          <path key={i} d={`M122 ${1000 - i * 36} H${160 + (i % 3) * 16}`} stroke="#8c867a" strokeWidth={5} opacity={recibo > 40 + i * 36 ? 1 : 0} />
        ))}
        <rect x={60} y={1010} width={200} height={300} rx={28} fill="url(#m-term)" stroke="#0b0f18" strokeWidth={4} />
        <rect x={84} y={1036} width={152} height={78} rx={10} fill="#4fd1a1" opacity={0.85} />
        <text x={160} y={1090} textAnchor="middle" fill="#0b2b20" fontFamily={FONT} fontWeight={800} fontSize={40}>{'TOTAL'}</text>
        {[0, 1, 2].map((r) => [0, 1, 2].map((c) => <rect key={r * 3 + c} x={92 + c * 50} y={1140 + r * 52} width={38} height={36} rx={8} fill="#586277" />))}
      </g>
      {/* formulario de solicitud que desliza */}
      <g transform={`translate(${px} ${py}) rotate(${-4 + Math.sin(s * 1.7) * 0.8})`}>
        <rect x={-230} y={-300} width={460} height={600} rx={18} fill="url(#m-paper)" stroke="#bdb4a2" strokeWidth={3} />
        <rect x={-230} y={-300} width={460} height={90} rx={18} fill="#B72833" />
        <text x={0} y={-238} textAnchor="middle" fill="#fff" fontFamily={FONT} fontWeight={900} fontSize={42} letterSpacing={2}>{'SOLICITUD'}</text>
        <Tarjeta x={0} y={-90} k={0.3} sombra={false} />
        <rect x={-190} y={30} width={34} height={34} rx={6} fill="#fff" stroke="#555" strokeWidth={4} />
        <path d="M-182 48 L-170 60 L-146 28" fill="none" stroke="#1d9e5b" strokeWidth={9} strokeLinecap="round" strokeLinejoin="round" strokeDasharray="90" strokeDashoffset={90 - check * 90} />
        <text x={-130} y={58} fill="#3a3a3a" fontFamily={FONT} fontWeight={700} fontSize={26}>{'Abrir tarjeta'}</text>
        {[0, 1, 2, 3].map((i) => <rect key={i} x={-190} y={100 + i * 36} width={380 - i * 50} height={11} rx={5} fill="#b9b2a4" />)}
        <path d="M-190 250 H100" stroke="#333" strokeWidth={4} />
        <text x={-190} y={242} fill="#333" fontFamily={FONT} fontWeight={800} fontSize={30}>{'X'}</text>
      </g>
      <Mano x={handX} y={py + 150 + 0} k={1.15} rot={-8} piel="#6B4430" sombra="#3e2417" luz="#9a6a4c" />
    </Escena0>
  );
};

// ------------------------------------------------------------------ E3
const E3: React.FC = () => {
  const {s, lin, spr} = useS();
  const tReg = en('regalo');
  const tFir = en('Firmas');
  const tDos = en('dos');
  const tVas = en('vas', 2);
  const tFeliz = en('feliz');
  const tDesc = en('descuento');
  const u = lin(tFir, tDos + 0.75, 0, 1, Easing.inOut(Easing.quad));
  const sample = (k: number): [number, number] => [540 - 230 + 440 * k, 1170 + 58 + Math.sin(k * Math.PI * 7) * 30 * (0.4 + 0.6 * Math.sin(k * Math.PI)) - k * 18];
