  for (let i = 0; i <= 70; i++) {
    const k = (i / 70) * u;
    const p = sample(k);
    pts.push(`${p[0].toFixed(1)},${p[1].toFixed(1)}`);
  }
  const tip = sample(u);
  const cardMove = lin(tFeliz + 0.45, tDesc + 0.2, 0, 1, Easing.inOut(Easing.cubic));
  const cy = 700 + cardMove * 1000;
  const ck = 1 - cardMove * 0.5;
