  const band = lin(tReg, tReg + 0.45, 0, 1, out);
  const bow = spr(tReg + 0.3, 9, 160);
  const hx = tip[0] + 110;
  const hy = tip[1] - 240;
  return (
    <Escena0 wall={WALL_RED} semilla={3}
      cam={[{t: starts[2], x: 540, y: 960, zoom: 1.0}, {t: 8.2, x: 590, y: 1050, zoom: 1.12}, {t: 9.5, x: 490, y: 1040, zoom: 1.12}, {t: 10.5, x: 540, y: 1000, zoom: 1.05}]}
      overlay={<Brillo x={540} y={1640} r={360} color="rgba(255,215,140,0.5)" t0={tDesc + 0.1} />}>
