      <g>
        <rect x={230} y={1020} width={620} height={300} rx={14} fill="url(#m-paper)" stroke="#bdb4a2" strokeWidth={3} />
        <text x={262} y={1070} fill="#B72833" fontFamily={FONT} fontWeight={900} fontSize={34} letterSpacing={3}>{'CONTRATO'}</text>
        {[0, 1].map((i) => <rect key={i} x={262} y={1088 + i * 26} width={430 - i * 90} height={9} rx={4} fill="#c6bfb0" />)}
        <path d="M290 1260 H790" stroke="#444" strokeWidth={4} />
        <text x={262} y={1256} fill="#444" fontFamily={FONT} fontWeight={800} fontSize={30}>{'X'}</text>
        <polyline points={pts.join(' ')} fill="none" stroke="#14295e" strokeWidth={8} strokeLinecap="round" strokeLinejoin="round" />
      </g>
      <CarteraAtras x={540} y={1650} k={1} />
      {flap < 0 && <Solapa x={540} y={1650} k={1} f={flap} />}
      {/* tarjeta con cinta de regalo */}
      <Tarjeta x={540} y={cy} k={ck} rot={-4 + Math.sin(s * 1.8) * 1.5}>
        <g clipPath="url(#m-cclip)">
          <g transform={`translate(0 -165) scale(1 ${band})`}><rect x={-38} y={0} width={76} height={330} fill="url(#m-gold)" /><rect x={-38} y={0} width={14} height={330} fill="#fff" opacity={0.3} /></g>
          <g transform={`translate(-260 0) scale(${band} 1)`}><rect x={0} y={-32} width={520} height={64} fill="url(#m-gold)" /><rect x={0} y={-32} width={520} height={12} fill="#fff" opacity={0.3} /></g>
        </g>
        <g transform={`scale(${bow})`}>
          <ellipse cx={-62} cy={-18} rx={62} ry={36} fill="url(#m-gold)" stroke="#8a5b10" strokeWidth={4} transform="rotate(-28 -62 -18)" />
          <ellipse cx={62} cy={-18} rx={62} ry={36} fill="url(#m-gold)" stroke="#8a5b10" strokeWidth={4} transform="rotate(28 62 -18)" />
          <circle cx={0} cy={-6} r={26} fill="#FFE08A" stroke="#8a5b10" strokeWidth={4} />
        </g>
      </Tarjeta>
      <CarteraFrente x={540} y={1650} k={1} />
      {flap >= 0 && <Solapa x={540} y={1650} k={1} f={flap} />}
      <Chispas x={540} y={700} t0={tFeliz} color={GOLD} r={300} n={10} />
      <Chispas x={540} y={1600} t0={tDesc + 0.15} color="#fff" r={260} n={8} />
      {/* mano que firma (primera persona) */}
