          <rect x={-100} y={-40} width={200} height={80} rx={18} fill="#14040a" stroke={GOLD} strokeWidth={5} />
          <text y={20} textAnchor="middle" fill={GOLD} fontFamily={FONT} fontWeight={900} fontSize={44}>{'1 VEZ'}</text>
        </g>
