  const strike = lin(tNo, tNo + 0.3, 0, 1);
  const flap = s < tVale ? -0.7 : lin(tVale, tPena - 0.05, -0.7, 1, Easing.in(Easing.quad));
  const shake = sacudida(s, [tComp], 22);
  return (
    <Escena0 wall={WALL_GOLD} luz="rgba(255,210,120,0.30)" semilla={7}
      cam={[{t: starts[6], x: 540, y: 960, zoom: 1.0}, {t: tComp, x: 540, y: 880, zoom: 1.35}, {t: 35.3, x: 540, y: 1000, zoom: 1.12}, {t: tPena, x: 540, y: 1010, zoom: 1.08}]}
      overlay={<><Chip texto="-15 %" x={540} y={1490} t0={tDesc} t1={tVale + 0.2} color={GOLD} size={68} /><svg width={1080} height={1920} style={{position: 'absolute', left: 0, top: 0}}><path d={`M430 1530 L${430 + 220 * strike} ${1530 - 80 * strike}`} stroke={RED} strokeWidth={12} strokeLinecap="round" opacity={strike > 0 && s < tVale + 0.5 ? 1 : 0} /></svg><Brillo x={540} y={1000} r={420} color="rgba(255,215,120,0.35)" t0={tComp} /></>}>
      <g transform={`translate(${shake.x} ${shake.y})`}>
        <Percheros />
        <Mostrador y={1500} />
        {/* recibo completo */}
        <g transform={`translate(540 ${1000 + Math.sin(s * 1.8) * 6}) rotate(${-2 + Math.sin(s * 1.3)})`}>
          <rect x={-280} y={-430} width={560} height={860} rx={14} fill="url(#m-paper)" stroke="#bdb4a2" strokeWidth={3} />
          <text x={0} y={-370} textAnchor="middle" fill="#B72833" fontFamily={FONT} fontWeight={900} fontSize={42} letterSpacing={4}>{'RECIBO'}</text>
          {Array.from({length: 9}).map((_, i) => (
            <g key={i}>
              <rect x={-230} y={-310 + i * 50} width={250 + (i % 3) * 40} height={12} rx={6} fill="#bdb6a8" />
              <rect x={150} y={-310 + i * 50} width={80} height={12} rx={6} fill="#bdb6a8" />
            </g>
          ))}
          <path d="M-230 190 H230" stroke="#444" strokeWidth={4} />
          <text x={-230} y={248} fill="#222" fontFamily={FONT} fontWeight={900} fontSize={44}>{'SALDO'}</text>
          <text x={230} y={248} textAnchor="end" fill="#222" fontFamily={FONT} fontWeight={900} fontSize={44}>{'$ 0'}</text>
          {s >= tComp && (
            <g transform={`translate(0 20) rotate(-12) scale(${0.6 + 0.4 * sello})`} opacity={cap(sello * 2)}>
              <rect x={-210} y={-78} width={420} height={156} rx={18} fill="none" stroke="#C99012" strokeWidth={10} />
              <rect x={-196} y={-64} width={392} height={128} rx={12} fill="none" stroke="#C99012" strokeWidth={3} />
              <text y={34} textAnchor="middle" fill="#C99012" stroke="#8a5b10" strokeWidth={2} fontFamily={FONT} fontWeight={900} fontSize={104} letterSpacing={4}>{'PAGADO'}</text>
            </g>
          )}
        </g>
        {/* sello dorado con la mano que paga */}
        <g transform={`translate(700 ${stampY})`}>
          <rect x={-110} y={60} width={220} height={44} rx={10} fill="url(#m-gold)" stroke="#8a5b10" strokeWidth={4} />
          <rect x={-70} y={-30} width={140} height={90} rx={18} fill="#5a3a22" stroke="#2a180c" strokeWidth={4} />
          <rect x={-30} y={-100} width={60} height={80} rx={26} fill="#6d4628" stroke="#2a180c" strokeWidth={4} />
          <path d="M60 -130 L420 -420" stroke="#C48B64" strokeWidth={100} strokeLinecap="round" />
          <Mano x={95} y={-80} k={0.85} rot={90} piel="#D29A74" sombra="#8f5c3d" luz="#F2C7A5" />
        </g>
        {/* reloj que se detiene */}
        <g transform="translate(280 650)">
          <circle r={120} fill="url(#m-gold)" stroke={frozen ? '#8a5b10' : '#6b1220'} strokeWidth={6} />
          <circle r={98} fill="url(#m-face)" />
          {MESES.map((m, i) => <text key={i} x={Math.sin((i * 30 * Math.PI) / 180) * 74} y={-Math.cos((i * 30 * Math.PI) / 180) * 74 + 9} textAnchor="middle" fill="#3a2f20" fontFamily={FONT} fontWeight={800} fontSize={22}>{m}</text>)}
          <g transform={`rotate(${mini})`}><path d="M0 18 V-74" stroke={frozen ? GOLD : RED} strokeWidth={10} strokeLinecap="round" /></g>
          <circle r={12} fill="url(#m-gold)" stroke="#8a5b10" strokeWidth={3} />
        </g>
        {/* meses pagados completos */}
        {[0, 1, 2].map((i) => {
          const a = spr(cajas[i], 10, 220);
          return a > 0.01 ? (
            <g key={i} transform={`translate(${470 + i * 130} 640) scale(${a})`}>
              <rect x={-52} y={-52} width={104} height={104} rx={16} fill="#fff" stroke={GOLD} strokeWidth={6} />
              <text y={-18} textAnchor="middle" fill="#555" fontFamily={FONT} fontWeight={800} fontSize={24}>{['MES 1', 'MES 2', 'MES 3'][i]}</text>
              <path d="M-24 16 L-6 36 L28 -4" fill="none" stroke="#1d9e5b" strokeWidth={12} strokeLinecap="round" strokeLinejoin="round" />
            </g>
          ) : null;
        })}
        {s >= tPoder && (
          <g transform={`translate(${470 + 3 * 130} 640) scale(${spr(tPoder, 8, 220)}) rotate(${golpe(s, tPoder, 22, 5) * 10})`}>
            <rect x={-52} y={-52} width={104} height={104} rx={16} fill="#fff" stroke={RED} strokeWidth={6} />
            <text y={-18} textAnchor="middle" fill="#555" fontFamily={FONT} fontWeight={800} fontSize={24}>{'MES 4'}</text>
            <text y={36} textAnchor="middle" fill={RED} fontFamily={FONT} fontWeight={900} fontSize={60}>{'!'}</text>
          </g>
        )}
        <CarteraAtras x={540} y={1700} k={0.8} />
        {flap < 0 && <Solapa x={540} y={1700} k={0.8} f={flap} />}
        <CarteraFrente x={540} y={1700} k={0.8} />
        {flap >= 0 && <Solapa x={540} y={1700} k={0.8} f={flap} />}
        <Ondas x={700} y={950} t0={tComp} color={GOLD} radio={560} />
        <Chispas x={540} y={1000} t0={tComp + 0.05} color={GOLD} r={380} n={12} />
      </g>
    </Escena0>
  );
};

// ------------------------------------------------------------------ E8 (bucle con E1)
const E8: React.FC = () => {
  const {s, spr} = useS();
  const tLike = en('like');
  const tCaja = en('CAJA');
  const tEnv = en('envíaselo');
  const tSi = en('sí', 4);
  const heart = spr(tLike + 0.05, 9, 200);
  const bubble = spr(tCaja, 9, 200);
  const rot = -6 + Math.sin(s * 1.4) * 1.2;
  const bob = Math.sin(s * 2.2) * 10;
  return (
    <Escena0 wall={WALL_RED} cam={[{t: starts[7], x: 540, y: 960, zoom: 1.12}, {t: 41, x: 560, y: 990, zoom: 1.06}, {t: 43.2, x: 540, y: 960, zoom: 1.0}]}
      overlay={<><Brillo x={540} y={1000 + bob} r={430} color="rgba(255,210,150,0.38)" /><Chip texto="sí" x={800} y={1480} t0={tSi} color={GOLD} size={72} /></>}>
      <Percheros />
      <Cartel />
      <Mostrador y={1300} />
      <TarjetaEtiqueta x={540} y={1000 + bob} rot={rot} peel={0} pop={1 + 0.06 * golpe(s, tCaja, 14, 5)} beat={1} />
      {/* corazón del like */}
      <g transform={`translate(190 700) scale(${heart * (1 + 0.08 * Math.sin(s * 6))}) rotate(-10)`}>
        <path d="M0 52 C-130 -30 -70 -130 0 -62 C70 -130 130 -30 0 52Z" fill={RED} stroke="#7a1520" strokeWidth={6} />
        <path d="M-52 -40 C-70 -20 -62 0 -50 12" fill="none" stroke="#fff" strokeWidth={9} strokeLinecap="round" opacity={0.6} />
      </g>
      {/* comentario CAJA */}
      <g transform={`translate(560 600) scale(${bubble})`}>
        <path d="M-150 -60 H150 Q170 -60 170 -40 V40 Q170 60 150 60 H-60 L-110 110 L-100 60 H-150 Q-170 60 -170 40 V-40 Q-170 -60 -150 -60Z" fill="#fff" stroke={GOLD} strokeWidth={6} />
        <text y={26} textAnchor="middle" fill="#B72833" fontFamily={FONT} fontWeight={900} fontSize={76} letterSpacing={3}>{'CAJA'}</text>
      </g>
      {/* avión de papel: envíaselo */}
      <Recorrido puntos={[[60, 1560], [420, 1330], [800, 760], [1160, 420]]} t0={tEnv} t1={tEnv + 1.3} color="rgba(255,200,61,0.85)"
        render={(x, y, ang) => (
          <g transform={`translate(${x} ${y}) rotate(${ang})`}>
            <path d="M60 0 L-60 -42 L-34 0 L-60 42Z" fill="#fff" stroke="#8a7a60" strokeWidth={4} />
            <path d="M60 0 L-34 0" stroke="#bdb4a2" strokeWidth={4} />
          </g>
        )} />
    </Escena0>
  );
};

// ------------------------------------------------------------------ Montaje
export const Escena: React.FC = () => {
  const {s} = useS();
  let body: React.ReactNode;
  if (s < starts[1]) body = <E1 />;
  else if (s < starts[2]) body = <E2 />;
  else if (s < starts[4]) body = <Paso t={starts[3]} tipo="alejar" x={THUMB.x} y={THUMB.y} antes={<E3 />} despues={<E4 />} />;
  else if (s < starts[7]) {
    const px = 540 + (THUMB.x - C5.x) * C5.z;
    const py = 960 + (THUMB.y - C5.y) * C5.z;
    body = (
      <Paso t={starts[6]} tipo="barrido"
        antes={<Paso t={starts[5]} tipo="entrar" x={px} y={py} antes={<E5 />} despues={<E6 />} />}
        despues={<E7 />} />
    );
  } else body = <E8 />;
  return <AbsoluteFill style={{background: '#12050a'}}>{body}</AbsoluteFill>;
};

